sql.where:
p.deleted = 0

    AND (
        p.title LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.approach LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.note LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.source LIKE CONCAT('%', #{q.keyword}, '%')
    )


    AND p.difficulty IN
    #{d}


    AND p.status IN
    #{s}


    AND p.id IN (
        SELECT li.problem_id FROM problem_list_item li WHERE li.list_id = #{q.listId}
    )



    AND p.id IN (
        SELECT pt.problem_id FROM problem_tag pt
        WHERE pt.tag_id IN
        #{t}
        GROUP BY pt.problem_id
        HAVING COUNT(DISTINCT pt.tag_id) = #{q.tagCount}
    )

mapper.select:
SELECT FROM problem p WHERE p.deleted = 0
AND p.status = #{status}
AND p.id NOT IN #{e}
ORDER BY RAND() LIMIT 1
